integration_nfeatures <- 3000
pca_dimensions <- 50
anchor_dimensions <- 1:30

get_layers_safe <- function(object, assay = "RNA") {
  as.character(
    tryCatch(
      Layers(object[[assay]]),
      error = function(e) character(0)
    )
  )
}

get_layer_matrix <- function(object, assay = "RNA", layer) {
  matrix <- LayerData(object, assay = assay, layer = layer)

  if (!inherits(matrix, "dgCMatrix")) {
    matrix <- as(matrix, "dgCMatrix")
  }

  matrix
}

ensure_data_layer <- function(object, assay = "RNA") {
  layers_present <- get_layers_safe(object, assay = assay)

  if ("data" %in% layers_present) {
    return(object)
  }

  data_candidates <- layers_present[grepl("^data($|\\.)", layers_present)]

  if (length(data_candidates) > 0) {
    source_layer <- data_candidates[[1]]
    message("Creating ", assay, "/data from ", source_layer)

    source_matrix <- LayerData(object, assay = assay, layer = source_layer)

    object <- SetAssayData(
      object,
      assay = assay,
      layer = "data",
      new.data = source_matrix
    )
    return(object)
  }

  count_candidates <- layers_present[grepl("^counts($|\\.)", layers_present)]

  if (length(count_candidates) > 0) {
    source_layer <- count_candidates[[1]]
    message("Creating ", assay, "/data from ", source_layer)

    source_matrix <- LayerData(object, assay = assay, layer = source_layer)

    object <- SetAssayData(
      object,
      assay = assay,
      layer = "data",
      new.data = source_matrix
    )

    return(object)
  }

  stop(
    "No data-like or counts-like layer was found in assay ",
    assay,
    ". Available layers: ",
    paste(layers_present, collapse = ", ")
  )
}

check_counts_layer <- function(object, layer, assay = "RNA", label) {
  matrix <- get_layer_matrix(object, assay = assay, layer = layer)

  fraction_noninteger <- if (length(matrix@x) > 0) {
    mean(abs(matrix@x - round(matrix@x)) > 1e-6)
  } else {
    0
  }

  value_range <- if (length(matrix@x) > 0) {
    range(matrix@x)
  } else {
    c(0, 0)
  }

  tibble(
    dataset = label,
    assay = assay,
    layer = layer,
    genes = nrow(matrix),
    cells = ncol(matrix),
    nonzero_values = length(matrix@x),
    fraction_noninteger = fraction_noninteger,
    min_value = value_range[[1]],
    max_value = value_range[[2]]
  )
}

canonicalize_label <- function(x) {
  x <- as.character(x)
  x <- tolower(x)
  x <- gsub("_", " ", x)
  x <- gsub("\\s+", " ", x)
  trimws(x)
}
harmonize_adult_cell_type <- function(cell_type) {
  original <- as.character(cell_type)
  canonical <- canonicalize_label(original)

  mapping <- c(
    "b cell" = "immune",
    "classical monocyte" = "immune",
    "monocyte" = "immune",
    "immune cell" = "immune",
    "leukocyte" = "immune",
    "macrophage" = "immune",
    "mast cell" = "immune",
    "mature nk t cell" = "immune",
    "myeloid dendritic cell" = "immune",
    "neutrophil" = "immune",
    "plasma cell" = "immune",
    "plasmacytoid dendritic cell" = "immune",
    "t cell" = "immune",
    "cd4-positive, alpha-beta t cell" = "immune",
    "cd8-positive, alpha-beta t cell" = "immune",
    "hematopoietic precursor cell" = "immune",

    "oocyte" = "germ",

    "epithelial cell" = "epithelial",
    "ovarian surface epithelial cell" = "epithelial",
    "glandular secretory epithelial cell" = "epithelial",

    "stromal cell" = "stroma",
    "stromal cell of ovary" = "stroma",

    "theca cell" = "theca",
    "theca stroma" = "theca",

    "blood vessel smooth muscle cell" = "mural",
    "smooth muscle pericyte" = "mural",
    "pericyte" = "mural",

    "endothelial cell" = "endothelial",

    "glial cell" = "glial",
    "unknown" = "unknown"
  )

  harmonized <- original
  hit <- canonical %in% names(mapping)

  harmonized[hit] <- unname(mapping[canonical[hit]])

  # Keep this adult population separate from mural, matching the established
  # project decision.
  harmonized[canonical == "smooth muscle cell"] <- "smooth muscle cell"

  harmonized
}

write_count_table <- function(metadata, column, file) {
  if (!column %in% colnames(metadata)) {
    return(invisible(NULL))
  }

  out <- metadata |>
    count(.data[[column]], name = "n_cells") |>
    arrange(desc(n_cells))

  colnames(out)[1] <- column

  write_csv(out, file)

  invisible(NULL)
}
compute_rna_layer_coverage <- function(object) {
  layers <- get_layers_safe(object, assay = "RNA")
  datasets <- sort(unique(as.character(object$dataset)))

  rows <- list()

  for (layer in layers) {
    layer_cells <- colnames(get_layer_matrix(object, assay = "RNA", layer = layer))

    for (dataset in datasets) {
      dataset_cells <- colnames(object)[as.character(object$dataset) == dataset]

      rows[[length(rows) + 1]] <- tibble(
        layer = layer,
        dataset = dataset,
        cells_in_dataset = length(dataset_cells),
        cells_in_layer = length(intersect(dataset_cells, layer_cells)),
        fraction_covered = ifelse(
          length(dataset_cells) > 0,
          length(intersect(dataset_cells, layer_cells)) / length(dataset_cells),
          NA_real_
        )
      )
    }
  }

  bind_rows(rows)
}

