  } else {
    stop("Fetal object is missing sampleID/sample_id metadata.")
  }
}

if (!"cell_type" %in% colnames(adult@meta.data)) {
  stop("Adult object is missing expected CELLxGENE cell_type metadata.")
}

if (!"donor_id" %in% colnames(adult@meta.data)) {
  stop("Adult object is missing expected donor_id metadata.")
}

fetal_layers <- get_layers_safe(fetal, assay = "RNA")
adult_layers <- get_layers_safe(adult, assay = "RNA")

if (!"counts" %in% adult_layers) {
  stop("Adult RNA assay must contain a counts layer for downstream pseudobulk.")
}

if (!"data" %in% adult_layers) {
  stop("Adult RNA assay must contain a data layer for integration.")
}

adult_matrix_qc <- bind_rows(
  check_counts_layer(adult, layer = "counts", assay = "RNA", label = "adult_counts"),
  check_counts_layer(adult, layer = "data", assay = "RNA", label = "adult_data")
)

write_csv(
  adult_matrix_qc,
  file.path(out_table_dir, "adult_reference_matrix_qc_before_integration.csv")
)

adult_counts_fraction_noninteger <- adult_matrix_qc$fraction_noninteger[
  adult_matrix_qc$dataset == "adult_counts"
]

adult_data_fraction_noninteger <- adult_matrix_qc$fraction_noninteger[
  adult_matrix_qc$dataset == "adult_data"
]

if (adult_counts_fraction_noninteger > 0.001) {
  stop("Adult RNA/counts is not count-like. Rerun adult reference preparation.")
}

if (adult_data_fraction_noninteger < 0.001) {
  warning("Adult RNA/data appears integer-like, but expected normalized/log-like data.")
}
fetal$dataset <- "fetal"
adult$dataset <- "adult"

fetal$developmental_stage <- "fetal"
adult$developmental_stage <- "adult"

# Compatibility with existing downstream scripts:
# fetal cell_type is the final major cell type;
# adult cell_type remains the original CELLxGENE label.
fetal$cell_type <- as.character(fetal$major_cell_type)
adult$adult_cell_type_original <- as.character(adult$cell_type)
adult$adult_cell_type_harmonized <- harmonize_adult_cell_type(adult$adult_cell_type_original)

fetal$fetal_major_cell_type <- as.character(fetal$major_cell_type)
fetal$fetal_fine_subcluster <- as.character(fetal$fine_subcluster)
fetal$fetal_final_annotation <- as.character(fetal$final_annotation)

adult$major_cell_type <- NA_character_
adult$fine_subcluster <- NA_character_
adult$final_annotation <- NA_character_
adult$annotation_version <- NA_character_
adult$annotation_source <- NA_character_
adult$fetal_major_cell_type <- NA_character_
adult$fetal_fine_subcluster <- NA_character_
adult$fetal_final_annotation <- NA_character_

fetal$adult_cell_type_original <- NA_character_
fetal$adult_cell_type_harmonized <- NA_character_

if (!"sampleID" %in% colnames(adult@meta.data)) {
  adult$sampleID <- NA_character_
}

if (!"donor_id" %in% colnames(fetal@meta.data)) {
  fetal$donor_id <- NA_character_
}

fetal <- ensure_data_layer(fetal, assay = "RNA")
adult <- ensure_data_layer(adult, assay = "RNA")

message("Fetal dimensions: ", nrow(fetal), " genes x ", ncol(fetal), " cells")
message("Adult dimensions: ", nrow(adult), " genes x ", ncol(adult), " cells")

common_features <- intersect(rownames(fetal), rownames(adult))

message("Common features: ", length(common_features))

if (length(common_features) <= 2000) {
  stop("Too few common features for integration: ", length(common_features))
}

write_csv(
  tibble(feature = common_features),
  file.path(out_table_dir, "fetal_adult_common_features.csv")
)

fetal_int <- subset(fetal, features = common_features)
adult_int <- subset(adult, features = common_features)

DefaultAssay(fetal_int) <- "RNA"
DefaultAssay(adult_int) <- "RNA"
message("Normalizing fetal data.")
fetal_int <- NormalizeData(
  fetal_int,
  normalization.method = "LogNormalize",
  scale.factor = 1e4,
  verbose = FALSE
)

fetal_int <- FindVariableFeatures(
  fetal_int,
  selection.method = "vst",
  nfeatures = integration_nfeatures,
  verbose = FALSE
)

message("Using adult RNA/data as normalized/log-like expression; not running NormalizeData on adult.")

adult_int <- ensure_data_layer(adult_int, assay = "RNA")

adult_int <- FindVariableFeatures(
  adult_int,
  selection.method = "mvp",
  nfeatures = integration_nfeatures,
  verbose = FALSE
)

features_use <- union(
  VariableFeatures(fetal_int),
  VariableFeatures(adult_int)
)

features_use <- intersect(features_use, common_features)

message("Integration features: ", length(features_use))

if (length(features_use) <= 500) {
  stop("Too few integration features: ", length(features_use))
}

write_csv(
  tibble(feature = features_use),
  file.path(out_table_dir, "fetal_adult_integration_features.csv")
)

message("Scaling and running PCA for fetal dataset.")
fetal_int <- ScaleData(
  fetal_int,
  features = features_use,
  verbose = FALSE
)

fetal_int <- RunPCA(
  fetal_int,
  features = features_use,
  npcs = pca_dimensions,
  verbose = FALSE
)

message("Scaling and running PCA for adult dataset.")
adult_int <- ScaleData(
  adult_int,
  features = features_use,
  verbose = FALSE
)
adult_int <- RunPCA(
  adult_int,
  features = features_use,
  npcs = pca_dimensions,
  verbose = FALSE
)

message("Finding RPCA integration anchors.")
anchors <- FindIntegrationAnchors(
  object.list = list(fetal_int, adult_int),
  anchor.features = features_use,
  reduction = "rpca",
  dims = anchor_dimensions
)

message("Integrating data.")
integrated <- IntegrateData(
  anchorset = anchors,
  dims = anchor_dimensions
)

DefaultAssay(integrated) <- "integrated"

integrated_layers <- get_layers_safe(integrated, assay = "integrated")

if (!"data" %in% integrated_layers) {
  stop("Integrated assay does not contain a data layer.")
}

message("Running integrated PCA and UMAP.")
integrated <- ScaleData(
  integrated,
  verbose = FALSE
)

integrated <- RunPCA(
  integrated,
  npcs = pca_dimensions,
  verbose = FALSE
)

integrated <- RunUMAP(
  integrated,
  reduction = "pca",
  dims = anchor_dimensions,
  verbose = FALSE
)

is_fetal <- as.character(integrated$dataset) == "fetal"
is_adult <- as.character(integrated$dataset) == "adult"

integrated$cell_type_joint <- NA_character_
integrated$cell_type_joint[is_fetal] <- as.character(integrated$cell_type[is_fetal])
integrated$cell_type_joint[is_adult] <- as.character(integrated$adult_cell_type_harmonized[is_adult])

integrated$celltype_prefixed <- paste0(
  as.character(integrated$dataset),
  ": ",
  integrated$cell_type_joint
)
if (anyNA(integrated$cell_type_joint)) {
  stop("cell_type_joint contains missing values after harmonization.")
}

expected_cells <- ncol(fetal) + ncol(adult)

stopifnot(
  ncol(integrated) == expected_cells,
  all(c("pca", "umap") %in% names(integrated@reductions)),
  "RNA" %in% names(integrated@assays),
  "integrated" %in% names(integrated@assays),
  "cell_type" %in% colnames(integrated@meta.data),
  "adult_cell_type_harmonized" %in% colnames(integrated@meta.data),
  "cell_type_joint" %in% colnames(integrated@meta.data),
  "celltype_prefixed" %in% colnames(integrated@meta.data),
  "sampleID" %in% colnames(integrated@meta.data),
  "donor_id" %in% colnames(integrated@meta.data)
)

rna_layer_coverage <- compute_rna_layer_coverage(integrated)

write_csv(
  rna_layer_coverage,
  file.path(out_table_dir, "fetal_adult_integrated_rna_layer_coverage.csv")
